////////////////////////////////////////
UINT16 utilDataMgr_SourceColorTableGet(eSOURCE_TYPE eType, UINT16 eSourceCM, UINT16 ePreCM)
{
    if((eType < eSOURCE_TYPE_NUMBER) && (eSourceCM < eCM_SOURCE_NUMBER) && (ePreCM < eCM_PICTURE_SETTINGS_NUMBER))
    {
        return m_cSourceTableMtached[(eType*eCM_SOURCE_NUMBER*eCM_PICTURE_SETTINGS_NUMBER) + (eSourceCM*eCM_PICTURE_SETTINGS_NUMBER) + ePreCM];
    }

    return eDATA_NODE_NUMBER;
}

UINT16 utilDataMgr_SourceColorTableUserGet(eSOURCE_TYPE eType, UINT16 eSourceCM, UINT16 ePreCM)
{
    if((eType < eSOURCE_TYPE_NUMBER) && (eSourceCM < eCM_SOURCE_NUMBER) && (ePreCM < eCM_PICTURE_SETTINGS_NUMBER))
    {
        return m_cSourceTableUserModeMtached[(eType*eCM_SOURCE_NUMBER*eCM_PICTURE_SETTINGS_NUMBER) + (eSourceCM*eCM_PICTURE_SETTINGS_NUMBER) + ePreCM];
    }

    return eDATA_NODE_NUMBER;
}

UINT16 utilDataMgr_SourceCommonTableGet(UINT16 eSourceCM)
{
    if(eSourceCM < eCM_SOURCE_NUMBER)
    {
        return m_cSourceTableCommon[eSourceCM];
    }

    return eDATA_NODE_NUMBER;
}

UINT16 utilDataMgr_WapTableGet(eWAP_PARA ePara, UINT16 eModeCM)
{
    if((ePara < eWAP_PARA_NUMBERS) && (eModeCM < eCM_PICTURE_SETTINGS_NUMBER))
    {
        switch(ePara)
        {
            case eWAP_PARA_PWM_100:
                return m_sWAP_Table[eModeCM].uiPWM_100;
            case eWAP_PARA_PWM_50:
                return m_sWAP_Table[eModeCM].uiPWM_50;
            case eWAP_PARA_PWM_30:
                return m_sWAP_Table[eModeCM].uiPWM_30;
            case eWAP_PARA_PWM_10:
                return m_sWAP_Table[eModeCM].uiPWM_10;
            default:
                return eDATA_NODE_NUMBER;

        }
    }

    return eDATA_NODE_NUMBER;
}


