void utilDataMgr_WriteGecLog_CM(UINT32 ulIndex)	//HICC2_Doulas_0003
{
    char cStrTemp[128] = {'\0'};
    UINT16 uiCount = 0;
    UINT16 uiStrlen = 0;
    uOPD_DATA uOPDData = {0};
#ifdef PLATFORM_H30_4K
    UINT8 ucBurnInEnable = ets_OFF;
	UINT8 ucValue = ets_OFF;
#endif

    for(uiCount = 0; uiCount < eERROR_LIST_INVALID; uiCount++)
    {
        if(sGEC_ERRORCODE_TABLE[uiCount].uiErrorIndex == ulIndex)
        {
            if( strcmp(sGEC_ERRORCODE_TABLE[uiCount].ERROREVENT, "") == 0 ) //G100_Simon_0060
            {
                sprintf(cStrTemp, "Error Code 0x%08x\0", sGEC_ERRORCODE_TABLE[uiCount].uiErrorIndex);
                uiStrlen = strlen(cStrTemp);
            }
            else
            {
                sprintf(cStrTemp, "%s\0", sGEC_ERRORCODE_TABLE[uiCount].ERROREVENT);
                uiStrlen = strlen(cStrTemp);
            }
            break;
        }
    }

    if(uiCount >= eERROR_LIST_INVALID)  //G100_Simon_0060
    {
        uOPDData.sErrorLog.dwGECCode = ulIndex;
        snprintf(uOPDData.sErrorLog.cString, 127, "%s (%d)\0", "Undefined", lErrorRefVal);
        utilOPD_EventSet(eOPD_ERROR_LOG, &uOPDData);
        palDataMgr_OPDSnapshot(eOPD_SNAPSHOT_LOG);
        return;
    }

    if(sGEC_ERRORCODE_TABLE[uiCount].ucWriteCheck == GEC_ERROR) //A70Gen2_Julie_0049
    {
		if(uiCount < eI2CError || (uiCount > eSPIError && uiCount < eI2Cwarn) || uiCount > eI2Cwarn32)
		{
		    utilDataMgr_WriteErrorLog(ulIndex, cStrTemp); //HICC2_Doulas_0031

#ifdef PLATFORM_H30_4K
            palDataMgr_Data_Access(edcBURNIN_ENABLE, edaREAD, &ucBurnInEnable);
            if(ucBurnInEnable == ets_ON)
            {
                palDataMgr_Data_Access(edcBURNIN_ENABLE, edaWRITE_THROUGH_WITH_ACTION, &ucValue);
                palDataMgr_Data_Access(edcBURN_IN, edaWRITE_THROUGH_WITH_ACTION, &ucValue);
            }
#endif
		}
    }

    uOPDData.sErrorLog.dwGECCode = ulIndex;
    snprintf(uOPDData.sErrorLog.cString, 127, "%s (%d)\0", cStrTemp, lErrorRefVal);

    if(sGEC_ERRORCODE_TABLE[uiCount].ucWriteCheck == GEC_ERROR)
    {
        utilOPD_EventSet(eOPD_ERROR_LOG, &uOPDData);
    }
    else if(sGEC_ERRORCODE_TABLE[uiCount].ucWriteCheck == GEC_WARNING) //A70LK_Larry_0110
    {
        utilOPD_EventSet(eOPD_WARNING_LOG, &uOPDData);
    }
    else if(sGEC_ERRORCODE_TABLE[uiCount].ucWriteCheck == GEC_REMINDER) //A70LK_Larry_0110
    {
        if(uiCount >= eI2CError01 && uiCount <= eI2CError32)
        {
            utilOPD_EventSet(eOPD_ERROR_LOG, &uOPDData);
        }
        else if(uiCount >= eI2Cwarn01 && uiCount <= eI2Cwarn32)
        {
            utilOPD_EventSet(eOPD_WARNING_LOG, &uOPDData);
        }
    }

	if((uiCount >= eLightModuleOverCurrent && uiCount <= eLightModuleShuntCurrent) ||
		(uiCount >= eLightModuleOCP && uiCount <= eLightModuleWarnTemp15) ||
		(uiCount >= eFanLock && uiCount <= eWheelStop02))
    {
       palDataMgr_OPDSnapshot(eOPD_SNAPSHOT_LOG);
    }

    if(uiCount == eInterLockSwitchFail) //G100_Owen_0064
    {
        palIllumination_InstantOff();
    }

#if defined(CUSTOM_CHRISTIE)
    switch(ulIndex)
    {
        case SystemOverTemp:
            palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_SYS_TEMP_ERROR, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_SYS_TEMP_ERROR);
            break;

        case SystemHighTemp:
            palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_SYS_TEMP_WARN, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_SYS_TEMP_WARN);
            break;

        case AmbientOverTemp:
            palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_AMBIENT_TEMP_ERROR, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_AMBIENT_TEMP_ERROR);
            break;

        case AmbientHighTemp:
            palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_AMBIENT_TEMP_WARN, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_AMBIENT_TEMP_WARN);
            break;

        case DMDOverTemp:
            palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_DMD_TEMP_ERROR, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_DMD_TEMP_ERROR);
            break;

        case DMDOverTemp02:
            palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_DMD_TEMP_WARN, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_DMD_TEMP_WARN);
            break;

        case LightModuleOverTemp:
            palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_BLD_TEMP_ERROR, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_BLD_TEMP_ERROR);
            break;

        case LightModuleWarnTemp01:
        case LightModuleWarnTemp02:
        case LightModuleWarnTemp03:
        case LightModuleWarnTemp04:
        case LightModuleWarnTemp05:
        case LightModuleWarnTemp06:
        case LightModuleWarnTemp07:
        case LightModuleWarnTemp08:
		case LightModuleWarnTemp09:
		case LightModuleWarnTemp10:
            palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_BLD_TEMP_WARN, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_BLD_TEMP_WARN);
            break;

		case TECOverTemp01:
            palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_RLD_TEMP_ERROR, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_RLD_TEMP_ERROR);
			break;

        case LightModuleWarnTemp11:
        case LightModuleWarnTemp12:
        case LightModuleWarnTemp13:
        case LightModuleWarnTemp14:
		case TECOverTemp02:
            palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_RLD_TEMP_WARN, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_RLD_TEMP_WARN);
			break;

		case LCSStall01:
            palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_PUMP_SPEED_ERROR, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_PUMP_SPEED_ERROR);
			break;

		case LCSStall03:
            palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_PUMP_SPEED_WARN, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_PUMP_SPEED_WARN);
			break;

        case FanStallError01:
        case FanStallError02:
        case FanStallError03:
        case FanStallError04:
        case FanStallError05:
        case FanStallError06:
        case FanStallError07:
        case FanStallError08:
        case FanStallError09:
		case FanStallError10:
		case FanStallError11:
		case FanStallError12:
            {
                UINT8 ucIndex = ulIndex&0xFF;
                palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_FAN1_SPEED_ERROR + ucIndex - 1, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_FAN1_SPEED_ERROR + ucIndex - 1);
            }
            break;

        case FanStallWarn01:
        case FanStallWarn02:
        case FanStallWarn03:
        case FanStallWarn04:
        case FanStallWarn05:
        case FanStallWarn06:
        case FanStallWarn07:
        case FanStallWarn08:
        case FanStallWarn09:
		case FanStallWarn10:
		case FanStallWarn11:
		case FanStallWarn12:
            {
                UINT8 ucIndex = ulIndex&0xFF;
                palDataMgr_UI_EventSend(edcOSD_WARNING_MESSAGE, eWARNING_MESSAGE_FAN1_SPEED_WARN + ucIndex - 1, NULL); //appGui_SendWarningMessage(eWARNING_MESSAGE_FAN1_SPEED_WARN + ucIndex - 1);
            }
            break;
    }
#endif /* CUSTOM_CHRISTIE */

    return;
}


